void require(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
std::unique_ptr<ScriptSession> start(const wchar_t* root,const wchar_t* map){Archives archives(root);archives.mountMap(map);auto world=World::read(archives);auto info=world->data().info;MapStrings strings;if(auto wts=archives.readCandidates({"war3map.wts"},ArchiveScope::Map))strings=mapStrings(wts->bytes);auto s=std::make_unique<ScriptSession>(jass::Module::compile(jass::Program::read(archives)),info,std::move(strings));s->campaignContext(false,1);s->attachWorld(std::move(world));s->audioSimulationClock();s->audioMuted(true);s->configure();PlayerSetup setup(info,s->config());s->applySetup(setup);s->startMain();return s;}
std::unique_ptr<ScriptSession> startOriginal(const wchar_t* root,const char* path,bool expansion=false,bool start=true){Archives archives(root);auto source=archives.readCandidates({path},ArchiveScope::Common);require(bool(source),"Original campaign map missing");archives.mountMap(std::make_shared<const Bytes>(source->bytes),path);auto world=World::read(archives);auto info=world->data().info;MapStrings strings;if(auto wts=archives.readCandidates({"war3map.wts"},ArchiveScope::Map))strings=mapStrings(wts->bytes);auto s=std::make_unique<ScriptSession>(jass::Module::compile(jass::Program::read(archives)),info,std::move(strings));s->campaignContext(expansion,1);s->attachWorld(std::move(world));s->audioSimulationClock();s->audioMuted(true);s->configure();PlayerSetup setup(info,s->config());s->applySetup(setup);if(start)s->startMain();return s;}
bool victory(ScriptSession& s,const char* next){for(auto& [id,dialog]:s.dialogs())if(dialog->owners){require(!dialog->buttons.empty() && s.clickDialog(s.localPlayer().value_or(0),dialog->buttons.front()),"Victory dialog could not continue");break;}if(s.exitRequest()==SessionExit::None)return false;require(s.exitRequest()==SessionExit::ChangeLevel && s.nextLevel()==next,"Unexpected campaign transition");return true;}
void chapter5(const wchar_t* root){auto session=startOriginal(root,"Maps\\Campaign\\Orc05.w3m");auto& vm=session->runtime();for(int i=0;i<1600;++i)session->advance(.25);require(session->userControl(),"Chapter 5 opening did not finish");auto hero=vm.global("udg_Grom"),target=vm.global("udg_Cenarius");require(session->units().contains(hero.bits) && session->units().contains(target.bits),"Chapter 5 objective units missing");vm.invoke("SetHeroLevel",std::array{hero,vm.integer(7),vm.boolean(false)});vm.invoke("SetUnitUserData",std::array{hero,vm.integer(2468)});vm.invoke("SetUnitInvulnerable",std::array{target,vm.boolean(false)});vm.invoke("KillUnit",std::array{target});for(int i=0;i<1800;++i){session->advance(.25);if(victory(*session,"Maps\\Campaign\\Orc06.w3m")){require(session->results()[3] && *session->results()[3]==0,"Chapter 5 result was not victory");auto cache=vm.invoke("GetLastCreatedGameCacheBJ");require(vm.invoke("HaveStoredUnit",std::array{cache,vm.string("Orc08"),vm.string("Grom")}).bits,"Chapter 5 did not save Grom");auto next=startOriginal(root,"Maps\\Campaign\\Orc08.w3m");next->advance(60);next->advance(60);next->advance(20);auto& after=next->runtime();auto stored=after.invoke("GetLastCreatedGameCacheBJ");require(after.invoke("HaveStoredUnit",std::array{stored,after.string("Orc08"),after.string("Grom")}).bits,"Chapter 8 did not load Grom cache");auto thrall=after.global("udg_Thrall"),grom=after.global("udg_Grom");require(next->units().contains(thrall.bits) && next->units().contains(grom.bits),"Chapter 8 heroes missing");auto h=next->units().at(thrall.bits),g=next->units().at(grom.bits);for(auto& [id,u]:next->units())if(id!=thrall.bits)u->paused=true;g->paused=false;h->paused=false;h->mana=h->maxMana=jass::Real::fromInteger(1000);after.invoke("SetUnitInvulnerable",std::array{thrall,after.boolean(true)});after.invoke("SetUnitInvulnerable",std::array{grom,after.boolean(false)});after.invoke("SetPlayerAlliance",std::array{after.handle("player",0x100000),after.handle("player",0x100000+g->owner),after.handle("alliancetype",0),after.boolean(false)});auto real=[&](int n){return after.real(jass::Real::fromInteger(n));};after.invoke("SetUnitPosition",std::array{thrall,real(0),real(0)});after.invoke("SetUnitPosition",std::array{grom,real(100),real(0)});after.invoke("FogEnable",std::array{after.boolean(false)});after.invoke("FogMaskEnable",std::array{after.boolean(false)});std::uint32_t gem=0;for(auto id:h->inventory)if(id && next->items().contains(id) && next->items().at(id)->type==ObjectData::code("gsou"))gem=id;require(gem && next->useItem(thrall.bits,gem,grom.bits),"Chapter 8 Soul Gem use failed");next->advance(4);auto rect=after.global("gg_rct_Jaina_COP");after.invoke("SetUnitPosition",std::array{thrall,after.invoke("GetRectCenterX",std::array{rect}),after.invoke("GetRectCenterY",std::array{rect})});auto skip=after.global("gg_trg_Thrall_Gets_to_COP_with_Grom_Cin_Skip");bool ready=false;for(int tick=0;tick<800;++tick){next->advance(.25);if(after.invoke("IsTriggerEnabled",std::array{skip}).bits){ready=true;break;}}require(ready,"Chapter 8 cinematic skip was not available");auto lastCreated=after.invoke("GetLastCreatedUnit");require(next->units().contains(lastCreated.bits) && next->units().at(lastCreated.bits)->type==ObjectData::code("oshm"),"Chapter 8 last created unit was not the purge shaman");require(next->endCinematic(next->localPlayer().value_or(0)),"Chapter 8 cinematic skip failed");next->advance(.25);auto loaded=after.global("bj_lastLoadedUnit"),referenced=after.global("udg_Grom");require(loaded.bits && next->units().contains(loaded.bits) && after.invoke("GetHeroLevel",std::array{loaded}).bits==7 && after.invoke("GetUnitUserData",std::array{loaded}).bits==2468,"Chapter 8 did not restore Grom cache");require(referenced.bits==lastCreated.bits && referenced.bits!=loaded.bits && after.invoke("GetLastCreatedUnit").bits==lastCreated.bits,"Chapter 8 did not preserve the original BJ last-created reference");for(int tick=0;tick<600 && next->exitRequest()==SessionExit::None;++tick){next->advance(.25);for(auto& [id,dialog]:next->dialogs())if(dialog->owners && !dialog->buttons.empty()){require(next->clickDialog(next->localPlayer().value_or(0),dialog->buttons.front()),"Chapter 8 victory dialog could not continue");break;}}require(next->exitRequest()==SessionExit::Return && next->results()[0] && *next->results()[0]==0,"Chapter 8 skip did not complete victory");std::cout<<"PASS Orc05 victory, Orc08 Grom cache and skip victory time="<<session->simulationTime()<<"\n";return;}}throw std::runtime_error("Chapter 5 victory not reached");}
void questPowerups(const wchar_t* root){auto s=startOriginal(root,"Maps\\FrozenThrone\\Campaign\\OrcX01_05.w3x",true);auto& vm=s->runtime();auto real=[&](int value){return vm.real(jass::Real::fromInteger(value));};auto hero=vm.invoke("CreateUnit",std::array{vm.invoke("Player",std::array{vm.integer(0)}),vm.integer(int(ObjectData::code("Hpal"))),real(0),real(0),real(0)});require(hero.bits && s->units().contains(hero.bits),"Quest collector missing");vm.invoke("SetUnitPathing",std::array{hero,vm.boolean(false)});auto before=vm.global("udg_ShimmerweedObtained").bits;auto herb=vm.invoke("CreateItem",std::array{vm.integer(int(ObjectData::code("shwd"))),real(0),real(0)});auto picked=vm.invoke("UnitAddItem",std::array{hero,herb});require(vm.global("udg_ShimmerweedObtained").bits==before+1,"Original Shimmerweed trigger did not advance");require(picked.bits && !s->items().contains(herb.bits),"Quest powerup was not consumed after pickup");require(!vm.invoke("UnitAddItem",std::array{hero,herb}).bits && vm.global("udg_ShimmerweedObtained").bits==before+1,"Consumed quest powerup triggered pickup again");auto eggs=vm.global("udg_EggsObtained").bits;auto egg=vm.invoke("CreateItem",std::array{vm.integer(int(ObjectData::code("thle"))),real(64),real(0)});PlayerCommand order;order.player=0;order.kind=PlayerCommandKind::TargetOrder;order.units={hero.bits};order.target=egg.bits;order.order=851971;require(dispatchPlayerCommand(*s,order)==1,"Quest egg pickup order rejected");for(int i=0;i<160 && s->items().contains(egg.bits);++i)s->advance(.125);require(!s->items().contains(egg.bits) && vm.global("udg_EggsObtained").bits==eggs+1,"Original egg trigger or pickup failed");require(!GetModuleHandleW(L"Game.dll"),"Game.dll loaded");std::cout<<"PASS original quest powerup pickup and counters\nRESULT passed=1 failed=0 game_dll_loaded=false\n";}
