void originalFogSnapshot(const wchar_t* root){auto first=startOriginal(root,"Maps\\FrozenThrone\\Campaign\\OrcX01.w3x",true),second=startOriginal(root,"Maps\\FrozenThrone\\Campaign\\OrcX01.w3x",true,false);for(int i=0;i<600;++i)first->advance(.25);auto clock=first->encodeSimulationClock(),players=first->encodePlayerConfiguration(),stats=first->encodePlayerStatistics();auto identity=[](std::string_view,std::uint32_t id){return id;};auto cache=first->runtime().global("bj_lastCreatedGameCache");require(cache.bits,"Original gamecache missing");first->runtime().invoke("StoreInteger",std::array{cache,first->runtime().string("SnapshotProbe"),first->runtime().string("value"),first->runtime().integer(728)});auto caches=first->encodeGameCaches(identity),fog=first->encodeFogState(identity);second->restoreSimulationClock(clock);second->restorePlayerConfiguration(players);second->restorePlayerStatistics(stats);auto cacheMapping=second->rebuildGameCaches(caches);require(cacheMapping.contains(cache.bits),"Original gamecache identity missing");auto restoredCache=second->runtime().handle("gamecache",cacheMapping.at(cache.bits));require(second->runtime().invoke("GetStoredInteger",std::array{restoredCache,second->runtime().string("SnapshotProbe"),second->runtime().string("value")}).bits==728,"Original gamecache unsaved value missing");auto cacheReverse=[&](std::string_view,std::uint32_t id){for(auto [oldId,newId]:cacheMapping)if(newId==id)return oldId;return std::uint32_t(0);};require(second->encodeGameCaches(cacheReverse)==caches,"Original gamecache state did not round-trip");auto mapping=second->rebuildFogState(fog);require(!mapping.empty(),"Original campaign has no fog modifier identities");auto reverse=[&](std::string_view,std::uint32_t id){for(auto [oldId,newId]:mapping)if(newId==id)return oldId;return std::uint32_t(0);};require(second->encodePlayerConfiguration()==players && second->encodePlayerStatistics()==stats && second->encodeFogState(reverse)==fog,"Original campaign player and fog states did not round-trip");require(!GetModuleHandleW(L"Game.dll"),"Game.dll loaded");std::cout<<"PASS original OrcX01 player, gamecache and fog snapshot round-trip\nRESULT passed=1 failed=0 game_dll_loaded=false\n";}
void originalTimerSnapshot(const wchar_t* root){auto first=startOriginal(root,"Maps\\FrozenThrone\\Campaign\\OrcX01.w3x",true),second=startOriginal(root,"Maps\\FrozenThrone\\Campaign\\OrcX01.w3x",true,false);for(int i=0;i<600;++i)first->advance(.25);std::set<std::uint32_t> referenced;auto observe=[&](std::string_view type,std::uint32_t id){if(type=="timer")referenced.insert(id);return id;};first->runtime().encodeGlobals(observe);auto identity=[](std::string_view,std::uint32_t id){return id;};auto clock=first->encodeSimulationClock(),timers=first->encodeTimers(identity);second->restoreSimulationClock(clock);auto mapping=second->rebuildTimers(timers);for(auto id:referenced)require(mapping.contains(id),"Original global timer identity was not rebuilt");auto reverse=[&](std::string_view type,std::uint32_t id){for(auto [oldId,newId]:mapping)if(type=="timer" && newId==id)return oldId;return std::uint32_t(0);};require(second->encodeTimers(reverse)==timers,"Original timer snapshot did not round-trip");require(!GetModuleHandleW(L"Game.dll"),"Game.dll loaded");std::cout<<"PASS original OrcX01 timer identities count="<<mapping.size()<<"\nRESULT passed=1 failed=0 game_dll_loaded=false\n";}
void heroes(ScriptSession& s){auto& vm=s.runtime();for(auto name:{"udg_Thrall","udg_Cairne"}){auto unit=vm.global(name);require(unit.bits && s.units().contains(unit.bits),"Campaign hero missing");require(vm.invoke("GetHeroLevel",std::array{unit}).bits==7 && vm.invoke("GetUnitUserData",std::array{unit}).bits==2468,"Campaign hero state was not restored");}}
void chapter6(ScriptSession& s){auto& vm=s.runtime();for(int tick=0;tick<2600;++tick){if(tick==720)for(auto name:{"udg_Thrall","udg_Cairne"}){auto u=vm.global(name);require(u.bits && s.units().contains(u.bits),"Chapter 6 hero missing");vm.invoke("SetHeroLevel",std::array{u,vm.integer(7),vm.boolean(false)});vm.invoke("SetUnitUserData",std::array{u,vm.integer(2468)});}if(tick==800){std::vector<std::uint32_t> enemies;for(auto& [id,u]:s.units())if(u->owner==1 && !u->removing && std::bit_cast<float>(u->life.bits())>0)enemies.push_back(id);require(!enemies.empty(),"Chapter 6 objective units missing");for(auto id:enemies)if(s.units().contains(id)){auto u=vm.handle("unit",id);vm.invoke("SetUnitInvulnerable",std::array{u,vm.boolean(false)});vm.invoke("KillUnit",std::array{u});}}s.advance(.25);if(victory(s,"Maps\\Campaign\\Orc07.w3m"))return;}throw std::runtime_error("Chapter 6 victory not reached");}
void chapter7(ScriptSession& s){auto& vm=s.runtime();heroes(s);for(int tick=0;tick<2600;++tick){if(tick==440)vm.invoke("TriggerExecute",std::array{vm.global("gg_trg_ObeliskThrallNoGem")});if(tick==600){auto hero=vm.global("udg_Cairne"),gem=vm.global("udg_EnchantedGemstone"),rect=vm.global("gg_rct_EnchantedGemStone");for(auto name:{"udg_Thrall","udg_Cairne"})vm.invoke("SetUnitInvulnerable",std::array{vm.global(name),vm.boolean(true)});require(vm.invoke("UnitAddItem",std::array{hero,gem}).bits!=0,"Chapter 7 gemstone pickup failed");vm.invoke("SetUnitPosition",std::array{hero,vm.invoke("GetRectCenterX",std::array{rect}),vm.invoke("GetRectCenterY",std::array{rect})});}if(tick==1000){require(vm.global("udg_GemstoneReturned").bits!=0,"Chapter 7 gemstone return failed");auto hero=vm.global("udg_Thrall"),rect=vm.global("gg_rct_OracleArea");vm.invoke("SetUnitPosition",std::array{hero,vm.invoke("GetRectCenterX",std::array{rect}),vm.invoke("GetRectCenterY",std::array{rect})});}s.advance(.25);if(victory(s,"Maps\\Campaign\\Orc08.w3m"))return;}throw std::runtime_error("Chapter 7 victory not reached");}
