int wmain(int argc,wchar_t** argv){try{if(argc==4 && std::wstring_view(argv[2])==L"timer-snapshot"){fs::path user(argv[3]);require(user.is_absolute() && fs::create_directory(user) && SetEnvironmentVariableW(L"MEGINE_WAR3_USER_DIR",user.c_str()),"User directory must be a new absolute directory with an existing parent");originalTimerSnapshot(argv[1]);return 0;}if(argc==4 && std::wstring_view(argv[2])==L"fog-snapshot"){fs::path user(argv[3]);require(user.is_absolute() && fs::create_directory(user) && SetEnvironmentVariableW(L"MEGINE_WAR3_USER_DIR",user.c_str()),"User directory must be a new absolute directory with an existing parent");originalFogSnapshot(argv[1]);return 0;}if(argc==4 && std::wstring_view(argv[2])==L"quest-shop"){fs::path user(argv[3]);require(user.is_absolute() && fs::create_directory(user) && SetEnvironmentVariableW(L"MEGINE_WAR3_USER_DIR",user.c_str()),"User directory must be a new absolute directory with an existing parent");questShop(argv[1]);return 0;}if(argc==4 && std::wstring_view(argv[2])==L"quest-powerup"){fs::path user(argv[3]);require(user.is_absolute() && fs::create_directory(user) && SetEnvironmentVariableW(L"MEGINE_WAR3_USER_DIR",user.c_str()),"User directory must be a new absolute directory with an existing parent");questPowerups(argv[1]);return 0;}if(argc==4 && std::wstring_view(argv[2])==L"chapter5"){fs::path user(argv[3]);require(user.is_absolute() && fs::create_directory(user) && SetEnvironmentVariableW(L"MEGINE_WAR3_USER_DIR",user.c_str()),"User directory must be a new absolute directory with an existing parent");chapter5(argv[1]);require(!GetModuleHandleW(L"Game.dll"),"Game.dll loaded");std::cout<<"RESULT passed=1 failed=0 game_dll_loaded=false\n";return 0;}if(argc!=6)throw std::runtime_error("Usage: war3_orc_campaign_chain_tests <data-root> <Orc06> <Orc07> <Orc08> <new-absolute-user-dir> | <data-root> <chapter5|quest-powerup|quest-shop|fog-snapshot|timer-snapshot> <new-absolute-user-dir>");fs::path user(argv[5]);require(user.is_absolute() && fs::create_directory(user),"User directory must be a new absolute directory with an existing parent");require(SetEnvironmentVariableW(L"MEGINE_WAR3_USER_DIR",user.c_str())!=0,"Cannot isolate campaign user directory");{auto s=start(argv[1],argv[2]);chapter6(*s);}{auto s=start(argv[1],argv[3]);chapter7(*s);}{auto s=start(argv[1],argv[4]);s->advance(10);heroes(*s);}require(!GetModuleHandleW(L"Game.dll"),"Game.dll loaded");std::cout<<"PASS Orc06 and Orc07 victory with Orc08 hero transfer\nRESULT passed=1 failed=0 game_dll_loaded=false\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
